    flowSP : REAL;
    valveCommand : REAL;
    fault : BOOL;
    normalMode : BOOL;
END_VAR
VAR
    prev_mode : INT := -1; (* 初始值非法，确保第一次 mode != prev_mode? 但首拍我们单独处理 *)
    prev_flowSP : REAL := 0.0;
    prev_valveCommand : REAL := 0.0;
    prev_eT : REAL := 0.0;
    prev_eF : REAL := 0.0;
